    void moduleReview(ModuleRegistry.Card card){open("module-review",card.label==null?card.appLabel:card.label,card.pkg);backAction=this::moduleOptions;if(card.error.isEmpty()){rowAction("允许显示卡片",card.caption.isEmpty()?"应用仍以自身权限运行":card.caption,()->{try{ModuleRegistry.decide(a,card,true);moduleOptions();}catch(Exception e){a.toast(e.getMessage());}});rowAction("不显示卡片","保留普通应用入口",()->{try{ModuleRegistry.decide(a,card,false);moduleOptions();}catch(Exception e){a.toast(e.getMessage());}});}scrollBody();body.addView(text(card.error.isEmpty()?"开发者签名 SHA-256\n"+card.signer:card.error,18,MUTED),lp(-1,-2));first();}
    void addonCatalog(){open("addon-catalog","扩展目录","上游独立应用 · 不是预装功能");backAction=()->settings("extensions");scrollBody();for(AddonCatalog.Addon addon:AddonCatalog.all())rowAction(addon.name,addon.description+(AddonCatalog.installed(a,addon.pkg)?" · 已安装":" · 未安装"),()->addonDetails(addon));first();}
