    void files(String purpose,String path){a.maintenance.run("浏览电视下载目录",()->{TvAdb.downloadPath(path);return a.maintenance.adb.shell("ls -1p "+TvAdb.quote(path));},listing->{open("download-files","选择文件",path);backAction=purpose.equals("cleanup")?this::maintenance:purpose.equals("apk")?this::addonCatalog:()->settings("desktop");scrollBody();if(!path.equals("/sdcard/Download/")){String trimmed=path.endsWith("/")?path.substring(0,path.length()-1):path;String parent=trimmed.substring(0,trimmed.lastIndexOf('/')+1);rowAction("上一级",parent,()->files(purpose,parent));}int count=0;for(String name:listing.split("\n")){if(name.isEmpty()||name.equals(".")||name.equals("..")||name.startsWith("."))continue;boolean dir=name.endsWith("/");String target=path+name;String lower=name.toLowerCase(Locale.ROOT);if(!dir&&!lower.endsWith(purpose.equals("apk")?".apk":".json")&&!(purpose.equals("cleanup")&&lower.endsWith(".txt")))continue;if(++count>120)break;rowAction(name,dir?"文件夹":"选择并预览",()->{if(dir)files(purpose,target);else a.acceptDownload(purpose,target);});}if(count==0)body.addView(text("目录中没有匹配文件",22,MUTED),lp(-1,80));first();});}
